def solve(g, allow_subset=False):
    H,W=len(g),len(g[0]); S={(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v}
    miss_color={(0,0):2,(1,0):3,(0,1):4,(1,1):5}
    wins=[]
    for r in range(H-1):
        for c in range(W-1):
            win=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            inS=[p for p in win if p in S]
            if len(inS)>=3: wins.append((win,inS))
    results=[]
    def rec(rem,used,acc):
        if not rem:
            gg=[[0]*W for _ in range(H)]
            for win,cov in acc:
                if len(cov)==4: col=1
                else:
                    m=[p for p in win if p not in cov]
                    if len(m)!=1: return
                    col=miss_color[(m[0][0]-win[0][0],m[0][1]-win[0][1])]
                for r,c in cov: gg[r][c]=col
            results.append(gg); return
        p=min(rem)
        seen=set()
        for win,inS in wins:
            if p not in win: continue
            avail=[x for x in inS if x not in used]
            opts=[avail] if len(avail) in (3,4) else []
            if allow_subset and len(avail)==4:
                opts += [list(c) for c in itertools.combinations(avail,3)]
            for cov in opts:
                if p not in cov: continue
                key=tuple(sorted(cov))
                if key in seen: continue
                seen.add(key)
                rec(rem-set(cov), used|set(cov), acc+[(win,cov)])
    rec(set(S),set(),[])
    return results
